import{a as d,_ as r}from"./chunks/npu_3510_hw_arch_sync.ByinXTj7.js";import{_ as e,o as a,a as f,b as o}from"./app.C41L12d5.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"数据搬运导览","link":"/api/SIMD-API/basic_api/data_move_guide/data_move_guide"},{"text":"概览","link":"/api/SIMD-API/basic_api/data_move_guide/overview/overview"},{"text":"数据通路","link":"/api/SIMD-API/basic_api/data_move_guide/overview/data_path"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/data_move_guide/overview/data_path.md","filePath":"api/SIMD-API/basic_api/data_move_guide/overview/data_path.md","outlineHeaders":[{"level":2,"title":"AI Core硬件架构与存储单元","slug":"AI-Core硬件架构与存储单元","link":"#AI-Core硬件架构与存储单元"},{"level":2,"title":"数据通路与搬运流水","slug":"数据通路与搬运流水","link":"#数据通路与搬运流水"}],"lastUpdated":1788329934000}'),l={name:"api/SIMD-API/basic_api/data_move_guide/overview/data_path.md"};function B(i,t,u,L,p,M){return a(),f("div",null,[...t[0]||(t[0]=[o('<div><article class="markdown-body"><h1>数据通路<span id="ZH-CN_TOPIC_0000002535040662"></span></h1><h2 id="AI-Core硬件架构与存储单元">AI Core硬件架构与存储单元<a class="header-anchor" href="#AI-Core硬件架构与存储单元">​</a></h2><div data-filter="910b,A3"><p>AI Core是昇腾处理器的核心计算单元，以<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本2201</a>为例，其内部分层存储架构如图1所示，主要包含以下组成部分：</p><ul><li><strong>计算单元（图中黄色高亮）：</strong> 包括Cube（矩阵）计算单元、Vector（矢量）计算单元和Scalar（标量）计算单元，分别负责矩阵乘加、向量运算和标量控制流。</li><li><strong>存储单元：</strong> 按层级由外到内依次为Global Memory（GM，位于AI Core外部）、L1 Buffer、L0A/L0B/L0C Buffer、Unified Buffer（UB）、BiasTable Buffer、Fixpipe Buffer等。各存储单元的容量与对齐要求各异，详情参见<a href="./overall_constraints.html#%E5%9C%B0%E5%9D%80%E5%AF%B9%E9%BD%90%E7%BA%A6%E6%9D%9F">内存层级架构</a>。</li><li><strong>搬运单元（图中黄色高亮）：</strong> 包括MTE1（Memory Transfer Engine 1）、MTE2、MTE3和FixPipe，负责数据在不同存储单元之间的DMA传输。其中MTE2负责GM -&gt; Local Memory方向的搬运，MTE3负责Local Memory -&gt; GM方向的搬运，MTE1负责L1 Buffer -&gt; L0 Buffer方向的数据搬运，FixPipe负责将计算结果从L0C Buffer中通过<a href="../../cube_compute_ISASI/cube_store_key_features/accompanying_quantization.html">随路量化</a>和<a href="../../cube_compute_ISASI/cube_store_key_features/accompanying_relu.html">随路激活</a>的方式搬出。</li></ul><p><strong>图 1</strong> NPU架构版本2201下，AI Core硬件架构示意图</p><p><img src="'+d+'" alt></p></div><div data-filter="950"><p>以<a href="../../../../../guide/programming_guide/language_extension/simd_builtin_keywords.html">NPU架构版本3510</a>为例，其内部分层存储架构如图2所示，该架构在数据通路上有如下变化：</p><ul><li>新增L0C Buffer到UB的单向数据通路。</li><li>新增UB到L1 Buffer的数据通路。</li><li>删除GM到L0A Buffer、L0B Buffer的数据通路。</li><li>删除L1 Buffer到GM的数据通路。</li></ul><p><strong>图 2</strong> NPU架构版本3510下，AI Core硬件架构示意图</p><p><img src="'+r+'" alt></p></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><ul><li>同一个物理内存可能对应多个不同的<a href="../../../basic_api/aux_data_structures/TPosition.html">TPosition</a>，例如UB同时映射到VECIN、VECCALC和VECOUT三个逻辑位置，分别代表矢量计算的输入、中间计算和输出阶段。L1 Buffer同时映射到A1、B1、C1和TSCM，具体含义取决于当前所服务的计算流程（矩阵左/右矩阵暂存或共享通信）。这种设计使得同一物理内存可以在不同计算阶段被赋予不同的逻辑语义，开发者可根据编程模型的阶段需求选择合适的TPosition。</li><li>同一个逻辑位置，在不同产品型号中可能对应不同的物理内存，例如逻辑位置CO2在Atlas A2 训练系列产品/Atlas A2 推理系列产品中映射到Global Memory，而在Atlas训练及推理系列产品中映射到UB，详细情况请参考<a href="../../../general_description_and_constraints.html#section1359919519819">逻辑位置和物理存储的映射关系</a>。</li></ul></div><h2 id="数据通路与搬运流水">数据通路与搬运流水<a class="header-anchor" href="#数据通路与搬运流水">​</a></h2><p>基于上述存储单元和搬运单元，AI Core内的数据通路及其对应的<a href="../../sync_control/intra_core_sync/intra_core_sync_overview.html#zh-cn_topic_0000002542725361_section1272612276459">硬件流水</a>如下表所示。每条数据通路指定了源（SRC）与目的（DST）存储单元，以及执行搬运的硬件流水，理解这些通路是选择正确数据搬运接口参数的基础。</p><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>下表为所有产品型号的数据通路汇总。具体每条数据通路是否在特定产品上支持，请以对应API接口文档中的产品支持情况表格为准。</p></div><p><strong>表 1</strong> 数据搬运功能总览<span id="table1151112542363"></span></p><table><thead><tr><th>源（SRC）</th><th>目的（DST）</th><th>流水（Pipeline）</th><th>功能</th><th>支持的API</th></tr></thead><tbody><tr><td>Global Memory</td><td>L1 Buffer</td><td>MTE2</td><td>将Global Memory中的矩阵数据连续搬运至L1 Buffer做中转。</td><td>DataCopy</td></tr><tr><td>Global Memory</td><td>L1 Buffer</td><td>MTE2</td><td>将Global Memory中的矩阵数据通过高维切分方式搬运至L1 Buffer做中转。</td><td>DataCopy</td></tr><tr><td>Global Memory</td><td>L1 Buffer</td><td>MTE2</td><td>将Global Memory中的矩阵数据搬运到L1 Buffer的同时实现ND到NZ格式的随路转换。</td><td>DataCopy</td></tr><tr><td>Global Memory</td><td>L1 Buffer</td><td>MTE2</td><td>将Global Memory中的矩阵数据搬运到L1 Buffer的同时实现DN到NZ格式的随路转换。</td><td>DataCopy</td></tr><tr><td>Global Memory</td><td>L1 Buffer</td><td>MTE2</td><td>将Global Memory中的非对齐数据搬运至L1 Buffer，并对边界无效区域做Padding填充。</td><td>DataCopyPad</td></tr><tr><td>Global Memory</td><td>L1 Buffer</td><td>MTE2</td><td>将Global Memory中的NZ格式数据搬运至L1 Buffer。</td><td>LoadData（2D矩阵搬运）</td></tr><tr><td>Global Memory</td><td>L1 Buffer</td><td>MTE2</td><td>将Global Memory中的NZ格式数据搬运至L1 Buffer。</td><td>LoadData（2D矩阵搬运V2）</td></tr><tr><td>Global Memory</td><td>L0A Buffer</td><td>MTE2</td><td>将Global Memory中的2D格式分形矩阵搬运至L0A Buffer作为矩阵计算的左矩阵输入。</td><td>LoadData（2D矩阵搬运）</td></tr><tr><td>Global Memory</td><td>L0B Buffer</td><td>MTE2</td><td>将Global Memory中的2D格式分形矩阵搬运至L0B Buffer作为矩阵计算的右矩阵输入。</td><td>LoadData（2D矩阵搬运）</td></tr><tr><td>Global Memory</td><td>UB</td><td>MTE2</td><td>将Global Memory中的矩阵数据连续搬运至UB。</td><td>DataCopy</td></tr><tr><td>Global Memory</td><td>UB</td><td>MTE2</td><td>将Global Memory中的矩阵数据通过高维切分方式搬运至UB。</td><td>DataCopy</td></tr><tr><td>Global Memory</td><td>UB</td><td>MTE2</td><td>将Global Memory中的数据按切片方式搬运至UB。</td><td>DataCopy</td></tr><tr><td>Global Memory</td><td>UB</td><td>MTE2</td><td>将Global Memory中的数据搬运至UB的同时完成ND到NZ格式的随路转换。</td><td>DataCopy</td></tr><tr><td>Global Memory</td><td>UB</td><td>MTE2</td><td>将Global Memory中的数据以NDDMA方式多维搬运至UB。</td><td>DataCopy</td></tr><tr><td>Global Memory</td><td>UB</td><td>MTE2</td><td>将Global Memory中的非对齐数据搬运至UB，并对边界无效区域做Padding填充。</td><td>DataCopyPad</td></tr><tr><td>UB</td><td>Global Memory</td><td>MTE3</td><td>将UB中的数据连续搬运至Global Memory。</td><td>DataCopy</td></tr><tr><td>UB</td><td>Global Memory</td><td>MTE3</td><td>将UB中的数据通过高维切分方式搬运至Global Memory。</td><td>DataCopy</td></tr><tr><td>UB</td><td>Global Memory</td><td>MTE3</td><td>将UB中的数据按切片方式搬运至Global Memory。</td><td>DataCopy</td></tr><tr><td>UB</td><td>Global Memory</td><td>MTE3</td><td>将UB中的数据搬运到Global Memory的同时完成NZ到ND格式的随路转换。</td><td>DataCopy</td></tr><tr><td>UB</td><td>Global Memory</td><td>MTE3</td><td>将UB中的非对齐数据搬运至Global Memory，读取UB时使用dummy数据补齐，写入Global Memory时丢弃dummy数据。</td><td>DataCopyPad</td></tr><tr><td>UB</td><td>L1 Buffer</td><td>MTE3</td><td>将UB中的数据连续搬运至L1 Buffer。</td><td>DataCopy</td></tr><tr><td>UB</td><td>L1 Buffer</td><td>MTE3</td><td>将UB中的数据通过高维切分方式搬运至L1 Buffer。</td><td>DataCopy</td></tr><tr><td>UB</td><td>L1 Buffer</td><td>MTE3</td><td>将UB中的数据搬运到L1 Buffer的同时完成ND到NZ格式的随路转换。</td><td>DataCopy</td></tr><tr><td>UB</td><td>L1 Buffer</td><td>MTE3</td><td>将UB中的非对齐数据搬运到L1 Buffer，并对边界无效区域做Padding填充。</td><td>DataCopyPad</td></tr><tr><td>L1 Buffer</td><td>UB</td><td>MTE1</td><td>将L1 Buffer中的数据连续搬运至UB。</td><td>DataCopyL1ToUB</td></tr><tr><td>L1 Buffer</td><td>UB</td><td>MTE1</td><td>将L1 Buffer中的数据通过高维切分方式搬运至UB。</td><td>DataCopyL1ToUB</td></tr><tr><td>L1 Buffer</td><td>Global Memory</td><td>MTE3</td><td>将L1 Buffer中的数据连续搬运至Global Memory。</td><td>DataCopy</td></tr><tr><td>L1 Buffer</td><td>Global Memory</td><td>MTE3</td><td>将L1 Buffer中的数据通过高维切分方式搬运至Global Memory。</td><td>DataCopy</td></tr><tr><td>L1 Buffer</td><td>L0A Buffer</td><td>MTE1</td><td>将L1 Buffer中的2D格式分形矩阵搬运至L0A Buffer作为Cube矩阵乘的左矩阵输入。</td><td>LoadData（2D矩阵搬运）</td></tr><tr><td>L1 Buffer</td><td>L0A Buffer</td><td>MTE1</td><td>将L1 Buffer中的2D格式分形矩阵搬运至L0A Buffer作为Cube矩阵乘的左矩阵输入。</td><td>LoadData（2D矩阵搬运V2）</td></tr><tr><td>L1 Buffer</td><td>L0A Buffer</td><td>MTE1</td><td>将L1 Buffer中的2D格式分形矩阵搬运至L0A Buffer作为Cube矩阵乘的左矩阵输入。</td><td>LoadData（MX矩阵搬运）</td></tr><tr><td>L1 Buffer</td><td>L0A Buffer</td><td>MTE1</td><td>将L1 Buffer中的2D格式分形矩阵搬运至L0A Buffer的同时完成转置。</td><td>LoadDataWithTranspose</td></tr><tr><td>L1 Buffer</td><td>L0A Buffer</td><td>MTE1</td><td>将L1 Buffer中的3D格式分形矩阵搬运至L0A Buffer，支持3D-Tile规则搬运。</td><td>LoadData（卷积数据搬运）</td></tr><tr><td>L1 Buffer</td><td>L0A Buffer</td><td>MTE1</td><td>将L1 Buffer中的3D格式分形矩阵搬运至L0A Buffer，支持3D-Tile规则搬运，支持配置输出矩阵K轴方向偏移量。</td><td>LoadDataWithStride</td></tr><tr><td>L1 Buffer</td><td>L0B Buffer</td><td>MTE1</td><td>将L1 Buffer中的2D格式分形矩阵搬运至L0B Buffer作为Cube矩阵乘的右矩阵输入。</td><td>LoadData（2D矩阵搬运）</td></tr><tr><td>L1 Buffer</td><td>L0B Buffer</td><td>MTE1</td><td>将L1 Buffer中的2D格式分形矩阵搬运至L0B Buffer作为Cube矩阵乘的右矩阵输入。</td><td>LoadData（2D矩阵搬运V2）</td></tr><tr><td>L1 Buffer</td><td>L0B Buffer</td><td>MTE1</td><td>将L1 Buffer中的2D格式分形矩阵搬运至L0B Buffer作为Cube矩阵乘的右矩阵输入。</td><td>LoadData（MX矩阵搬运）</td></tr><tr><td>L1 Buffer</td><td>L0B Buffer</td><td>MTE1</td><td>将L1 Buffer中的2D格式分形矩阵搬运至L0B Buffer的同时完成转置。</td><td>LoadDataWithTranspose</td></tr><tr><td>L1 Buffer</td><td>L0B Buffer</td><td>MTE1</td><td>将L1 Buffer中的3D格式分形矩阵搬运至L0B Buffer，支持3D-Tile规则搬运。</td><td>LoadData（卷积数据搬运）</td></tr><tr><td>L1 Buffer</td><td>L0B Buffer</td><td>MTE1</td><td>将L1 Buffer中的3D格式分形矩阵搬运至L0B Buffer，支持3D-Tile规则搬运，支持配置输出矩阵K轴方向偏移量。</td><td>LoadDataWithStride</td></tr><tr><td>L1 Buffer</td><td>L0B Buffer</td><td>MTE1</td><td>将L1 Buffer中的稠密权重矩阵搬运至L0B Buffer，同时支持稀疏解压。</td><td>LoadDataWithSparse</td></tr><tr><td>L1 Buffer</td><td>BiasTable Buffer</td><td>MTE1</td><td>将L1 Buffer中的偏置数据连续搬运至BiasTable Buffer供矩阵计算使用。</td><td>DataCopy</td></tr><tr><td>L1 Buffer</td><td>BiasTable Buffer</td><td>MTE1</td><td>将L1 Buffer中的偏置数据通过高维切分方式搬运至BiasTable Buffer。</td><td>DataCopy</td></tr><tr><td>L1 Buffer</td><td>Fixpipe Buffer</td><td>FixPipe</td><td>将矩阵数据搬出需要的随路量化和随路relu参数从L1 Buffer连续搬运至Fixpipe Buffer。</td><td>DataCopy</td></tr><tr><td>L1 Buffer</td><td>Fixpipe Buffer</td><td>FixPipe</td><td>将矩阵数据搬出需要的随路量化和随路relu参数从L1 Buffer通过高维切分方式搬运至Fixpipe Buffer。</td><td>DataCopy</td></tr><tr><td>L0C Buffer</td><td>Global Memory</td><td>FixPipe</td><td>将Cube计算结果从L0C Buffer搬运到Global Memory，支持随路量化和激活后处理。</td><td>DataCopy</td></tr><tr><td>L0C Buffer</td><td>Global Memory</td><td>FixPipe</td><td>将Cube计算结果从L0C Buffer搬运到Global Memory，通过FixPipe流水完成量化、激活、格式转换。</td><td>FixPipe</td></tr><tr><td>L0C Buffer</td><td>L1 Buffer</td><td>FixPipe</td><td>将Cube计算结果从L0C Buffer搬运至L1 Buffer做中转，支持随路量化和激活。</td><td>DataCopy</td></tr><tr><td>L0C Buffer</td><td>L1 Buffer</td><td>FixPipe</td><td>将Cube计算结果从L0C Buffer搬运至L1 Buffer做中转，通过FixPipe完成量化、激活、格式转换。</td><td>FixPipe</td></tr><tr><td>L0C Buffer</td><td>UB</td><td>MTE3</td><td>将Cube计算结果从L0C Buffer搬运至UB，支持随路量化和激活后处理。</td><td>DataCopy</td></tr><tr><td>L0C Buffer</td><td>UB</td><td>PIPE_FIX</td><td>将Cube计算结果从L0C Buffer搬运至UB，通过FixPipe完成量化、激活、格式转换。</td><td>FixPipe</td></tr><tr><td>UB</td><td>UB</td><td>PIPE_V</td><td>UB内部连续数据搬移。</td><td>DataCopy</td></tr><tr><td>UB</td><td>UB</td><td>PIPE_V</td><td>UB内部通过高维切分方式搬移数据。</td><td>DataCopy</td></tr><tr><td>UB</td><td>UB</td><td>PIPE_V</td><td>UB内部连续数据搬移。</td><td>Copy</td></tr><tr><td>UB</td><td>UB</td><td>PIPE_V</td><td>UB内部掩码式高维数据搬移。</td><td>Copy</td></tr></tbody></table></article></div>',1)])])}const D=e(l,[["render",B]]);export{m as __pageData,D as default};
